# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor layer_norm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("layer_norm_forward", &layer_norm_forward, "Fused LayerNorm forward (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/ATen.h>

// One block per row; threads stride over norm_size elements.
__global__ void layer_norm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ y,
    int norm_size,
    float eps
) {
    extern __shared__ float smem[];

    int row = blockIdx.x;
    const float* x_row = x + row * norm_size;
    float* y_row = y + row * norm_size;

    // Step 1: compute mean
    float sum = 0.0f;
    for (int i = threadIdx.x; i < norm_size; i += blockDim.x) {
        sum += x_row[i];
    }
    smem[threadIdx.x] = sum;
    __syncthreads();
    // Block reduction
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            smem[threadIdx.x] += smem[threadIdx.x + stride];
        }
        __syncthreads();
    }
    float mean = smem[0] / (float)norm_size;
    __syncthreads();

    // Step 2: compute variance
    float var_sum = 0.0f;
    for (int i = threadIdx.x; i < norm_size; i += blockDim.x) {
        float diff = x_row[i] - mean;
        var_sum += diff * diff;
    }
    smem[threadIdx.x] = var_sum;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            smem[threadIdx.x] += smem[threadIdx.x + stride];
        }
        __syncthreads();
    }
    float variance = smem[0] / (float)norm_size;
    float inv_std = rsqrtf(variance + eps);
    __syncthreads();

    // Step 3: normalize and apply affine
    for (int i = threadIdx.x; i < norm_size; i += blockDim.x) {
        float val = (x_row[i] - mean) * inv_std;
        y_row[i] = val * weight[i] + bias[i];
    }
}

torch::Tensor layer_norm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
    // Guard: must be CUDA, contiguous, float32
    if (!x.is_cuda() || !x.is_contiguous() || x.scalar_type() != at::ScalarType::Float ||
        !weight.is_cuda() || !weight.is_contiguous() || weight.scalar_type() != at::ScalarType::Float ||
        !bias.is_cuda() || !bias.is_contiguous() || bias.scalar_type() != at::ScalarType::Float) {
        int64_t norm_size = weight.numel();
        std::vector<int64_t> ns = {norm_size};
        return at::layer_norm(x, ns, weight, bias, eps, false);
    }

    int64_t norm_size = weight.numel();
    if (norm_size <= 0 || x.numel() % norm_size != 0) {
        std::vector<int64_t> ns = {norm_size};
        return at::layer_norm(x, ns, weight, bias, eps, false);
    }

    int64_t outer = x.numel() / norm_size;
    auto y = torch::empty_like(x);

    int block_size = 256;
    if (norm_size < 256) {
        block_size = 64;
    } else if (norm_size >= 1024) {
        block_size = 512;
    }

    size_t smem = block_size * sizeof(float);
    layer_norm_kernel<<<(int)outer, block_size, smem>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        y.data_ptr<float>(),
        (int)norm_size,
        (float)eps
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    return y;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs Layer Normalization.
        """
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initializes the LayerNorm layer.

                Args:
                    normalized_shape (tuple): Shape of the input tensor to be normalized.
                """
        self.ln = nn.LayerNorm(normalized_shape=normalized_shape)
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Applies Layer Normalization to the input tensor.

                Args:
                    x (torch.Tensor): Input tensor of shape (*, normalized_shape).

                Returns:
                    torch.Tensor: Output tensor with Layer Normalization applied, same shape as input.
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if (x.is_cuda and x.is_contiguous() and
                self.ln.weight is not None and self.ln.bias is not None and
                self.ln.weight.is_cuda and self.ln.weight.is_contiguous() and
                self.ln.bias.is_cuda and self.ln.bias.is_contiguous() and
                x.dtype == torch.float32 and
                self.ln.weight.dtype == torch.float32 and
                self.ln.bias.dtype == torch.float32 and
                x.numel() % self.ln.weight.numel() == 0):
            return _stark_get_extension().layer_norm_forward(
                x, self.ln.weight, self.ln.bias, float(self.ln.eps)
            )
        return self.ln(x)
        # <<<END_IMPROVE>>>
